"""State-vector simulation and deterministic shot sampling."""

from __future__ import annotations

import cmath
import math
import random

from .gates import (
    PHASE_FACTORS,
    Operation,
    rotation_matrix,
)
from .openqasm import Program

_SQRT1_2 = 2.0**-0.5


def _hadamard(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = (a + b) * _SQRT1_2
            state[high] = (a - b) * _SQRT1_2


def _pauli_x(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            state[low], state[high] = state[high], state[low]


def _pauli_y(state: list[complex], qubit: int, num_qubits: int) -> None:
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = -1j * b
            state[high] = 1j * a


# Phase gates diag(1, phase): z, s/sdg (diag(1, +-i)) and t/tdg
# (phase exp(+-i*pi/4)). The factors come from the single gate registry so
# the state-vector path cannot diverge from the density/unitary matrices.
_PHASE_GATES = PHASE_FACTORS


def _phase(state: list[complex], qubit: int, num_qubits: int, factor: complex) -> None:
    bit = 1 << qubit
    for index in range(1 << num_qubits):
        if index & bit:
            state[index] = factor * state[index]


def _swap(state: list[complex], first: int, second: int, num_qubits: int) -> None:
    first_bit = 1 << first
    second_bit = 1 << second
    for index in range(1 << num_qubits):
        if (index & first_bit) and not (index & second_bit):
            other = (index ^ first_bit) | second_bit
            state[index], state[other] = state[other], state[index]


def _controlled_x(state: list[complex], control: int, target: int, num_qubits: int) -> None:
    cbit = 1 << control
    tbit = 1 << target
    for index in range(1 << num_qubits):
        if (index & cbit) and not (index & tbit):
            other = index | tbit
            if index < other:
                state[index], state[other] = state[other], state[index]


def _controlled_single(
    state: list[complex],
    control: int,
    target: int,
    num_qubits: int,
    matrix: tuple[complex, complex, complex, complex],
) -> None:
    """Apply a single-qubit matrix to *target* where the *control* bit is 1."""
    g00, g01, g10, g11 = matrix
    cbit = 1 << control
    tbit = 1 << target
    step = tbit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + tbit):
            if not (low & cbit):
                continue
            high = low | tbit
            a = state[low]
            b = state[high]
            state[low] = g00 * a + g01 * b
            state[high] = g10 * a + g11 * b


def _rx(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = c * a - 1j * s * b
            state[high] = -1j * s * a + c * b


def _ry(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    c = math.cos(theta / 2)
    s = math.sin(theta / 2)
    bit = 1 << qubit
    step = bit << 1
    for base in range(0, 1 << num_qubits, step):
        for low in range(base, base + bit):
            high = low | bit
            a = state[low]
            b = state[high]
            state[low] = c * a - s * b
            state[high] = s * a + c * b


def _rz(state: list[complex], qubit: int, num_qubits: int, theta: float) -> None:
    lo_factor = cmath.exp(-0.5j * theta)
    hi_factor = cmath.exp(0.5j * theta)
    bit = 1 << qubit
    for index in range(1 << num_qubits):
        if index & bit:
            state[index] = hi_factor * state[index]
        else:
            state[index] = lo_factor * state[index]


def _apply_gate(state: list[complex], op: Operation, num_qubits: int) -> None:
    """Apply one (non-measurement) *op* to *state* in place.

    The dispatch uses the gate's registered style and the single shared
    matrix expression in :mod:`quantum_circuit.gates`; only the numeric
    state-vector kernels below are local to this module.
    """
    kind = op.kind
    if kind == "x":
        _pauli_x(state, op.targets[0], num_qubits)
    elif kind == "h":
        _hadamard(state, op.targets[0], num_qubits)
    elif kind == "y":
        _pauli_y(state, op.targets[0], num_qubits)
    elif kind in _PHASE_GATES:
        _phase(state, op.targets[0], num_qubits, _PHASE_GATES[kind])
    elif kind == "swap":
        _swap(state, op.targets[0], op.targets[1], num_qubits)
    elif kind == "cx":
        _controlled_x(state, op.targets[0], op.targets[1], num_qubits)
    elif kind == "cz":
        _controlled_single(
            state, op.targets[0], op.targets[1], num_qubits, op.spec.target_unitary()
        )
    elif kind in ("rx", "ry", "rz"):
        axis = op.spec.axis
        if axis == "x":
            _rx(state, op.targets[0], num_qubits, op.params[0])
        elif axis == "y":
            _ry(state, op.targets[0], num_qubits, op.params[0])
        else:
            _rz(state, op.targets[0], num_qubits, op.params[0])
    else:
        # Controlled angle rotations crx/cry/crz: the target embedding is
        # the one matrix definition shared with the density path.
        matrix = rotation_matrix(op.spec.axis, op.params[0])
        _controlled_single(state, op.targets[0], op.targets[1], num_qubits, matrix)


def simulate_state_vector(program: Program) -> list[complex]:
    """Return the final state vector after applying all quantum gates.

    Basis-state integer ``k`` stores qubit ``i`` in bit ``i`` (q[0] is the
    least significant bit). Measurements do not collapse the state: the spec
    guarantees every measurement comes after every gate and each qubit is
    measured at most once, so non-destructive sampling of the final state is
    equivalent.
    """
    n = program.num_qubits
    state = [0j] * (1 << n)
    state[0] = 1 + 0j

    for op in program.operations:
        if op.kind == "measure":
            # Measurements affect only the sampled classical outcomes.
            continue
        _apply_gate(state, op, n)
    return state


def unitary_matrix(program: Program) -> list[list[complex]]:
    """Return the full unitary U induced by the gates (pre-measurement).

    The matrix acts on basis vectors with qubit ``i`` in bit ``i`` (q[0] is
    the least significant bit), matching :func:`simulate_state_vector`.
    Measurement operations are ignored. Columns are evolved independently by
    applying each gate in source order, so for a circuit with gates G1..Gk the
    result is U = Gk @ ... @ G1.
    """
    n = program.num_qubits
    dim = 1 << n
    gate_ops = [op for op in program.operations if op.kind != "measure"]

    columns: list[list[complex]] = []
    for start in range(dim):
        state = [0j] * dim
        state[start] = 1 + 0j
        for op in gate_ops:
            _apply_gate(state, op, n)
        columns.append(state)

    # Transpose columns-of-U into rows.
    return [[columns[col][row] for col in range(dim)] for row in range(dim)]


def measurement_probabilities(program: Program, basis_probabilities: list[float]) -> dict[str, float]:
    """Aggregate basis-state probabilities into classical-outcome probabilities.

    Uses the same qubit-to-clbit mapping as :func:`sample_counts` (each
    measured qubit contributes its bit to the classical index; unwritten
    clbits stay 0) and the same fixed-width, lexicographically ordered key
    convention. With no measurements the only possible outcome is the
    all-zero string, carrying total probability 1.
    """
    width = program.num_clbits
    measurements = [(op.targets[0], op.targets[1]) for op in program.operations if op.kind == "measure"]

    if not measurements:
        return {format(0, f"0{width}b") if width else "": 1.0}

    aggregated: dict[int, float] = {}
    for basis, probability in enumerate(basis_probabilities):
        classical = 0
        for qubit, clbit in measurements:
            if (basis >> qubit) & 1:
                classical |= 1 << clbit
        aggregated[classical] = aggregated.get(classical, 0.0) + probability

    return {
        format(classical, f"0{width}b") if width else "": probability
        for classical, probability in sorted(aggregated.items())
    }


def sample_counts(program: Program, state: list[complex], shots: int, seed: int) -> dict[str, int]:
    """Draw *shots* samples from *state* deterministically from *seed*.

    Returns a mapping from fixed-width classical bit strings (highest clbit
    index first) to occurrence counts. Only observed outcomes are present.
    """
    probabilities = [abs(amplitude) ** 2 for amplitude in state]
    return sample_counts_from_probabilities(program, probabilities, shots, seed)


def sample_counts_from_probabilities(
    program: Program, probabilities: list[float], shots: int, seed: int
) -> dict[str, int]:
    """Draw *shots* samples from explicit basis-state probabilities.

    Used by the density-matrix path, which supplies the diagonal of the
    final density matrix; sampling semantics match the state-vector path.
    """
    measurements = [(op.targets[0], op.targets[1]) for op in program.operations if op.kind == "measure"]

    total = sum(probabilities)
    cumulative = []
    running = 0.0
    for probability in probabilities:
        running += probability / total
        cumulative.append(running)
    if cumulative:
        cumulative[-1] = 1.0

    rng = random.Random(seed)
    width = program.num_clbits
    counts: dict[str, int] = {}
    for _ in range(shots):
        point = rng.random()
        # Binary search for the first cumulative value >= point.
        lo, hi = 0, len(cumulative)
        while lo < hi:
            mid = (lo + hi) // 2
            if cumulative[mid] < point:
                lo = mid + 1
            else:
                hi = mid
        basis = lo

        classical = 0
        for qubit, clbit in measurements:
            if (basis >> qubit) & 1:
                classical |= 1 << clbit
        key = format(classical, f"0{width}b") if width else ""
        counts[key] = counts.get(key, 0) + 1

    return dict(sorted(counts.items()))

"""Python DSL for building circuits over the OpenQASM 2.0 subset.

A :class:`Circuit` is created with a quantum and a classical register size
and extended by chaining gate and measurement methods, mirroring the
statements of the supported OpenQASM subset one to one::

    circuit = Circuit(2, 2).h(0).cx(0, 1).measure(0, 0).measure(1, 1)

Operations keep their insertion order and every chaining method returns the
same circuit object. The circuit renders to (:meth:`Circuit.to_qasm`) and
parses from (:meth:`Circuit.from_qasm`) the OpenQASM 2.0 subset text the
command line accepts, and simulates through the exact code paths of the
``simulate``, ``probabilities`` and ``expectation`` commands
(:meth:`Circuit.sample`, :meth:`Circuit.probabilities`,
:meth:`Circuit.expectation`), so the returned dictionaries match the
commands' JSON objects field by field.

Validation mirrors the parser's semantic rules: type mismatches raise
:class:`TypeError`, while out-of-range indices, non-finite angles and
semantic conflicts (control equal to target, repeated measurement, a gate
after a measurement) raise :class:`ValueError`. A rejected operation never
changes the circuit.
"""

from __future__ import annotations

import math
from collections.abc import Mapping

from .core import SimulationError, run_expectation, run_probabilities, run_simulation
from .gates import (
    Operation,
    gate_operation,
    gate_qasm,
    measurement_operation,
)
from .noise import validate_noise_model
from .observables import MAX_OBSERVABLES
from .openqasm import Program, parse

# Register sizes accepted by the DSL match the parser's limit.
_MIN_REGISTER_SIZE = 1
_MAX_REGISTER_SIZE = 20

_DEFAULT_SHOTS = 1024
_DEFAULT_SEED = 0


def _check_register_size(name: str, value: object) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            f"{name} must be an integer, got {type(value).__name__}"
        )
    if not _MIN_REGISTER_SIZE <= value <= _MAX_REGISTER_SIZE:
        raise ValueError(
            f"{name} must be between {_MIN_REGISTER_SIZE} and {_MAX_REGISTER_SIZE}, got {value}"
        )
    return value


def _check_index(register: str, value: object, size: int) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError(
            f"{register} index must be an integer, got {type(value).__name__}"
        )
    if not 0 <= value < size:
        raise ValueError(
            f"{register} index {value} out of range for register of size {size}"
        )
    return value


def _check_angle(value: object) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(
            f"angle must be an integer or float, got {type(value).__name__}"
        )
    angle = float(value)
    if not math.isfinite(angle):
        raise ValueError("angle must be a finite number")
    return angle


def _operation_line(op: Operation) -> str:
    """Render one operation as an OpenQASM statement (register names q/c)."""
    if op.kind == "measure":
        return f"measure q[{op.targets[0]}] -> c[{op.targets[1]}];"
    return gate_qasm(op.kind, op.targets, op.params[0] if op.params else None)


_OBSERVABLE_KEYS = ("id", "operators")
_OPERATOR_KEYS = ("qubit", "pauli")
_PAULIS = ("X", "Y", "Z")


def _check_observable_operators(
    operators: object, where: str, num_qubits: int
) -> list[tuple[int, str]]:
    if isinstance(operators, bool) or not isinstance(operators, (list, tuple)):
        raise TypeError(
            f"{where} 'operators' must be a list or tuple, "
            f"got {type(operators).__name__}"
        )
    parsed: list[tuple[int, str]] = []
    seen_qubits: set[int] = set()
    for op_index, operator in enumerate(operators):
        op_where = f"{where}.operators[{op_index}]"
        if not isinstance(operator, Mapping):
            raise TypeError(
                f"{op_where} must be a mapping, got {type(operator).__name__}"
            )
        for key in operator:
            if key not in _OPERATOR_KEYS:
                raise ValueError(f"{op_where} has unknown field {key!r}")

        if "qubit" not in operator:
            raise ValueError(f"{op_where} is missing required field 'qubit'")
        qubit = operator["qubit"]
        if isinstance(qubit, bool) or not isinstance(qubit, int):
            raise TypeError(
                f"{op_where} 'qubit' must be an integer, "
                f"got {type(qubit).__name__}"
            )
        if not 0 <= qubit < num_qubits:
            raise ValueError(
                f"{op_where} 'qubit' {qubit} out of range for register of "
                f"size {num_qubits}"
            )
        if qubit in seen_qubits:
            raise ValueError(f"{op_where} repeats qubit {qubit} within {where}")
        seen_qubits.add(qubit)

        if "pauli" not in operator:
            raise ValueError(f"{op_where} is missing required field 'pauli'")
        pauli = operator["pauli"]
        if not isinstance(pauli, str):
            raise TypeError(
                f"{op_where} 'pauli' must be a string, got {type(pauli).__name__}"
            )
        if pauli not in _PAULIS:
            raise ValueError(
                f"{op_where} 'pauli' must be one of 'X', 'Y', 'Z', got {pauli!r}"
            )

        parsed.append((qubit, pauli))
    return parsed


def _check_observables(
    observables: object, num_qubits: int
) -> list[tuple[str, list[tuple[int, str]]]]:
    """Validate one observables batch, returning ``(id, operators)`` pairs.

    Type mismatches raise :class:`TypeError`; size, field, identifier,
    qubit and Pauli violations raise :class:`ValueError`. The whole batch
    is checked before any state evolution happens.
    """
    if isinstance(observables, bool) or not isinstance(observables, (list, tuple)):
        raise TypeError(
            f"observables must be a list or tuple, got {type(observables).__name__}"
        )
    if not 1 <= len(observables) <= MAX_OBSERVABLES:
        raise ValueError(
            f"observables must contain between 1 and {MAX_OBSERVABLES} entries, "
            f"got {len(observables)}"
        )

    parsed: list[tuple[str, list[tuple[int, str]]]] = []
    seen_ids: set[str] = set()
    for index, item in enumerate(observables):
        where = f"observables[{index}]"
        if not isinstance(item, Mapping):
            raise TypeError(f"{where} must be a mapping, got {type(item).__name__}")
        for key in item:
            if key not in _OBSERVABLE_KEYS:
                raise ValueError(f"{where} has unknown field {key!r}")

        if "id" not in item:
            raise ValueError(f"{where} is missing required field 'id'")
        observable_id = item["id"]
        if not isinstance(observable_id, str):
            raise TypeError(
                f"{where} 'id' must be a string, got {type(observable_id).__name__}"
            )
        if not observable_id:
            raise ValueError(f"{where} 'id' must be a non-empty string")
        if observable_id in seen_ids:
            raise ValueError(f"duplicate observable id {observable_id!r}")
        seen_ids.add(observable_id)

        if "operators" not in item:
            raise ValueError(f"{where} is missing required field 'operators'")
        parsed.append(
            (
                observable_id,
                _check_observable_operators(item["operators"], where, num_qubits),
            )
        )
    return parsed


class Circuit:
    """A quantum circuit over the supported OpenQASM 2.0 subset.

    Created with the quantum and classical register sizes (integers from 1
    to 20, booleans rejected) and extended through the chaining gate and
    measurement methods, which return the circuit itself.
    """

    def __init__(self, num_qubits: int, num_clbits: int):
        self._num_qubits = _check_register_size("num_qubits", num_qubits)
        self._num_clbits = _check_register_size("num_clbits", num_clbits)
        self._operations: list[Operation] = []
        self._measured_qubits: set[int] = set()
        self._measured_clbits: set[int] = set()
        self._measurement_started = False

    # ------------------------------------------------------------ properties

    @property
    def num_qubits(self) -> int:
        return self._num_qubits

    @property
    def num_clbits(self) -> int:
        return self._num_clbits

    @property
    def operations(self) -> tuple[Operation, ...]:
        """The appended operations, in insertion order."""
        return tuple(self._operations)

    def __repr__(self) -> str:
        return (
            f"Circuit(num_qubits={self._num_qubits}, num_clbits={self._num_clbits}, "
            f"operations={len(self._operations)})"
        )

    # ------------------------------------------------------------------ gates

    def _qubit_index(self, value: object) -> int:
        return _check_index("qubit", value, self._num_qubits)

    def _clbit_index(self, value: object) -> int:
        return _check_index("clbit", value, self._num_clbits)

    def _check_gate_allowed(self, kind: str) -> None:
        if self._measurement_started:
            raise ValueError(f"quantum gate {kind!r} cannot be added after a measurement")

    def _append_gate(self, op: Operation) -> Circuit:
        # All validation has already happened in the calling method, so a
        # rejected operation never reaches this point and never mutates the
        # circuit.
        self._operations.append(op)
        return self

    def _fixed_single_gate(self, name: str, qubit: object) -> Circuit:
        target = self._qubit_index(qubit)
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (target,)))

    def _controlled_gate(self, name: str, control: object, target: object) -> Circuit:
        ctrl = self._qubit_index(control)
        tgt = self._qubit_index(target)
        if ctrl == tgt:
            raise ValueError(f"{name} control and target must be different qubits")
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (ctrl, tgt)))

    def _swap_gate(self, first: object, second: object) -> Circuit:
        a = self._qubit_index(first)
        b = self._qubit_index(second)
        if a == b:
            raise ValueError("swap operands must be different qubits")
        self._check_gate_allowed("swap")
        return self._append_gate(gate_operation("swap", (a, b)))

    def _rotation_gate(self, name: str, angle: object, qubit: object) -> Circuit:
        theta = _check_angle(angle)
        target = self._qubit_index(qubit)
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (target,), (theta,)))

    def _controlled_rotation_gate(
        self, name: str, angle: object, control: object, target: object
    ) -> Circuit:
        theta = _check_angle(angle)
        ctrl = self._qubit_index(control)
        tgt = self._qubit_index(target)
        if ctrl == tgt:
            raise ValueError(f"{name} control and target must be different qubits")
        self._check_gate_allowed(name)
        return self._append_gate(gate_operation(name, (ctrl, tgt), (theta,)))

    def x(self, qubit: int) -> Circuit:
        """Append an ``x`` gate on *qubit*."""
        return self._fixed_single_gate("x", qubit)

    def h(self, qubit: int) -> Circuit:
        """Append an ``h`` gate on *qubit*."""
        return self._fixed_single_gate("h", qubit)

    def y(self, qubit: int) -> Circuit:
        """Append a ``y`` gate on *qubit*."""
        return self._fixed_single_gate("y", qubit)

    def z(self, qubit: int) -> Circuit:
        """Append a ``z`` gate on *qubit*."""
        return self._fixed_single_gate("z", qubit)

    def s(self, qubit: int) -> Circuit:
        """Append an ``s`` gate on *qubit*."""
        return self._fixed_single_gate("s", qubit)

    def sdg(self, qubit: int) -> Circuit:
        """Append an ``sdg`` gate on *qubit*."""
        return self._fixed_single_gate("sdg", qubit)

    def t(self, qubit: int) -> Circuit:
        """Append a ``t`` gate on *qubit*."""
        return self._fixed_single_gate("t", qubit)

    def tdg(self, qubit: int) -> Circuit:
        """Append a ``tdg`` gate on *qubit*."""
        return self._fixed_single_gate("tdg", qubit)

    def cx(self, control: int, target: int) -> Circuit:
        """Append a ``cx`` gate from *control* to *target*."""
        return self._controlled_gate("cx", control, target)

    def cz(self, control: int, target: int) -> Circuit:
        """Append a ``cz`` gate from *control* to *target*."""
        return self._controlled_gate("cz", control, target)

    def swap(self, first: int, second: int) -> Circuit:
        """Append a ``swap`` gate exchanging *first* and *second*."""
        return self._swap_gate(first, second)

    def rx(self, angle: float, qubit: int) -> Circuit:
        """Append an ``rx(angle)`` gate on *qubit* (angle in radians)."""
        return self._rotation_gate("rx", angle, qubit)

    def ry(self, angle: float, qubit: int) -> Circuit:
        """Append an ``ry(angle)`` gate on *qubit* (angle in radians)."""
        return self._rotation_gate("ry", angle, qubit)

    def rz(self, angle: float, qubit: int) -> Circuit:
        """Append an ``rz(angle)`` gate on *qubit* (angle in radians)."""
        return self._rotation_gate("rz", angle, qubit)

    def crx(self, angle: float, control: int, target: int) -> Circuit:
        """Append a ``crx(angle)`` gate from *control* to *target*."""
        return self._controlled_rotation_gate("crx", angle, control, target)

    def cry(self, angle: float, control: int, target: int) -> Circuit:
        """Append a ``cry(angle)`` gate from *control* to *target*."""
        return self._controlled_rotation_gate("cry", angle, control, target)

    def crz(self, angle: float, control: int, target: int) -> Circuit:
        """Append a ``crz(angle)`` gate from *control* to *target*."""
        return self._controlled_rotation_gate("crz", angle, control, target)

    # ------------------------------------------------------------ measurement

    def measure(self, qubit: int, clbit: int) -> Circuit:
        """Append ``measure qubit -> clbit``.

        Each qubit and each clbit may take part in at most one measurement,
        and no quantum gate may be added once measurement has started.
        """
        q = self._qubit_index(qubit)
        c = self._clbit_index(clbit)
        if q in self._measured_qubits:
            raise ValueError(f"qubit {q} is measured more than once")
        if c in self._measured_clbits:
            raise ValueError(f"clbit {c} is the target of more than one measurement")
        self._measured_qubits.add(q)
        self._measured_clbits.add(c)
        self._measurement_started = True
        self._operations.append(measurement_operation(q, c))
        return self

    # --------------------------------------------------------------- OpenQASM

    def to_qasm(self) -> str:
        """Render the circuit as OpenQASM 2.0 subset text.

        Uses the fixed register names ``q`` and ``c``, emits the operations
        in insertion order with the same statement semantics as the parser,
        and ends with a trailing newline. Angles use the shortest decimal
        representation that round-trips to the same float (negative zero is
        written as ``0``).
        """
        lines = [
            "OPENQASM 2.0;",
            'include "qelib1.inc";',
            f"qreg q[{self._num_qubits}];",
            f"creg c[{self._num_clbits}];",
        ]
        lines.extend(_operation_line(op) for op in self._operations)
        return "\n".join(lines) + "\n"

    @classmethod
    def from_qasm(cls, source: str) -> Circuit:
        """Build a circuit from OpenQASM 2.0 subset text.

        Parsing and validation are exactly those of the command line:
        :class:`~quantum_circuit.openqasm.ParseError` and
        :class:`~quantum_circuit.openqasm.ValidationError` propagate with
        their 1-based line/column positions intact.
        """
        if not isinstance(source, str):
            raise TypeError(f"source must be a string, got {type(source).__name__}")
        program = parse(source)
        circuit = cls(program.num_qubits, program.num_clbits)
        for op in program.operations:
            # The program is fully validated, so these invariants hold.
            if op.kind == "measure":
                circuit._measured_qubits.add(op.targets[0])
                circuit._measured_clbits.add(op.targets[1])
                circuit._measurement_started = True
            circuit._operations.append(op)
        return circuit

    # -------------------------------------------------------------- simulation

    def _to_program(self) -> Program:
        return Program(self._num_qubits, self._num_clbits, tuple(self._operations))

    @staticmethod
    def _prepare_noise_model(noise_model: object) -> dict[str, float] | None:
        if noise_model is None:
            return None
        return validate_noise_model(noise_model)

    def sample(self, shots: int = _DEFAULT_SHOTS, seed: int = _DEFAULT_SEED, noise_model=None) -> dict:
        """Sample the circuit, returning the ``simulate`` payload as a dict.

        The result equals the JSON object the ``simulate`` command produces
        for :meth:`to_qasm` with the same *shots*, *seed* and noise model
        (defaults 1024 and 0). *noise_model* is a mapping with the four
        optional channels; invalid models raise
        :class:`~quantum_circuit.noise.NoiseModelError`. Each call samples
        from a fresh RNG seeded by *seed*, so repeated calls with equal
        arguments return equal results and no random state is shared. The
        circuit itself is never modified.
        """
        if isinstance(shots, bool) or not isinstance(shots, int):
            raise TypeError(f"shots must be an integer, got {type(shots).__name__}")
        if shots <= 0:
            raise ValueError(f"shots must be a positive integer, got {shots}")
        if isinstance(seed, bool) or not isinstance(seed, int):
            raise TypeError(f"seed must be an integer, got {type(seed).__name__}")
        model = self._prepare_noise_model(noise_model)
        program = self._to_program()
        try:
            return run_simulation(program, shots, seed, model)
        except SimulationError as exc:
            # The DSL reports the noisy size limit as a ValueError, matching
            # its other value-range errors rather than the CLI's exit code 3.
            raise ValueError(str(exc)) from None

    def probabilities(self, noise_model=None) -> dict:
        """Exact final-state measurement probabilities, as a dict.

        The result equals the JSON object the ``probabilities`` command
        produces for :meth:`to_qasm` with the same noise model. The circuit
        itself is never modified.
        """
        model = self._prepare_noise_model(noise_model)
        program = self._to_program()
        try:
            return run_probabilities(program, model)
        except SimulationError as exc:
            raise ValueError(str(exc)) from None

    def expectation(self, observables, noise_model=None) -> dict:
        """Pauli-product expectation values of the final pre-measurement state.

        *observables* is a list or tuple of 1 to 100 mappings, each with an
        ``id`` (a non-empty string, unique within the batch) and
        ``operators`` (a list or tuple of mappings with a ``qubit`` — a
        non-boolean integer inside the quantum register, not repeated
        within one entry — and a ``pauli`` of ``"X"``, ``"Y"`` or
        ``"Z"``). An empty ``operators`` sequence is the global identity.
        Type mismatches raise :class:`TypeError`; size, field, identifier,
        qubit and Pauli violations raise :class:`ValueError`, and the whole
        batch is validated before any state evolution happens.

        The result equals the JSON object the ``expectation`` command
        produces for :meth:`to_qasm` with the equivalent observables
        document and the same noise model, keeping the input order:
        ``schema_version``, ``num_qubits``, ``noise_model`` (``None``
        without a model) and ``results``, each result carrying the original
        ``id`` and its ``expectation`` in ``[-1, 1]``. Measurement mappings
        and the classical register width do not take part. Invalid noise
        models raise :class:`~quantum_circuit.noise.NoiseModelError`; a
        noisy circuit beyond the density-matrix qubit limit raises
        :class:`ValueError`. Repeated calls with equal arguments return
        equal results, and neither the circuit nor *observables* is
        modified.
        """
        parsed = _check_observables(observables, self._num_qubits)
        model = self._prepare_noise_model(noise_model)
        program = self._to_program()
        try:
            return run_expectation(program, model, parsed)
        except SimulationError as exc:
            raise ValueError(str(exc)) from None


